Here’s a **Quick Sort implementation in C** with clear comments:  

```c
#include <stdio.h>

// Function to swap two elements
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

// Partition function: places pivot element at correct position
// and places smaller elements on left and greater on right
int partition(int arr[], int low, int high) {
    int pivot = arr[high];  // choose last element as pivot
    int i = (low - 1);      // index of smaller element

    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {   // if current element is smaller than pivot
            i++;
            swap(&arr[i], &arr[j]);
        }
    }

    // place pivot in the correct position
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

// QuickSort function
void quickSort(int arr[], int low, int high) {
    if (low < high) {
        // Partition the array
        int pi = partition(arr, low, high);

        // Recursively sort elements before and after partition
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

// Utility function to print an array
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++)
        printf("%d ", arr[i]);
    printf("\n");
}

// Driver code
int main() {
    int arr[] = {10, 7, 8, 9, 1, 5};
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("Original array: ");
    printArray(arr, n);

    quickSort(arr, 0, n - 1);

    printf("Sorted array: ");
    printArray(arr, n);

    return 0;
}
```

---

### 🔑 Key Points:
- Quick Sort is **Divide & Conquer** like Merge Sort.
- **Pivot** divides the array into two halves:
  - Left: smaller than pivot  
  - Right: greater than pivot  
- Time complexity:  
  - **Best/Average** → O(n log n)  
  - **Worst (already sorted array with bad pivot choice)** → O(n²)  
- Space complexity: O(log n) (because of recursion stack).

